import matplotlib.pyplot as plt

def plot_k_vs_n(tuples):
    k_values = []
    n_values = []

    for n, k, s in tuples:
        k_values.append(k)
        n_values.append(n)

    plt.figure(figsize=(8, 5))
    plt.scatter(n_values, k_values, color='green', label='$n$ vs. $k$')
    plt.xlabel('$n$')
    plt.ylabel('$k$')
    plt.title('Plot of $k$ vs. $n$')
    plt.legend()
    plt.grid(True)
    plt.show()

